SELECT COUNT(*)
FROM reservation
WHERE device_id = #{deviceId}
  AND user_id != #{userId}
  AND status IN ('PENDING', 'CONFIRMED', 'IN_USE', 'PENDING_PAYMENT')
  AND start_time < #{endTime}
  AND end_time > #{startTime}

